while end &lt; children.len() &amp;&amp; expand(&amp;children[end]) { end += 1; }
// Also take hash：# 表达式的 # 号必须跟着表达式走
if start &gt; 0 &amp;&amp; children[start - 1].kind() == SyntaxKind::Hash { start -= 1; }
// 合成窗口起点的 at_start / nesting，以及窗口终点的期望值
